struct hstate {
	struct mutex resize_lock;
	int next_nid_to_alloc;
	int next_nid_to_free;
	unsigned int order;
	unsigned int demote_order;
	unsigned long mask;
	unsigned long max_huge_pages;
	unsigned long nr_huge_pages;
	unsigned long free_huge_pages;
	unsigned long resv_huge_pages;
	unsigned long surplus_huge_pages;
	unsigned long nr_overcommit_huge_pages;
	struct list_head hugepage_activelist;
	struct list_head hugepage_freelists[(1 << 6)];
	unsigned int max_huge_pages_node[(1 << 6)];
	unsigned int nr_huge_pages_node[(1 << 6)];
	unsigned int free_huge_pages_node[(1 << 6)];
	unsigned int surplus_huge_pages_node[(1 << 6)];

	struct cftype cgroup_files_dfl[8];
	struct cftype cgroup_files_legacy[10];

	char name[32];
};

struct huge_bootmem_page {
	struct list_head list;
	struct hstate *hstate;
};

int isolate_or_dissolve_huge_page(struct page *page, struct list_head *list);
struct folio *alloc_hugetlb_folio(struct vm_area_struct *vma,
				  unsigned long addr, int avoid_reserve);
struct folio *alloc_hugetlb_folio_nodemask(struct hstate *h, int preferred_nid,
					   nodemask_t *nmask, gfp_t gfp_mask);
struct folio *alloc_hugetlb_folio_vma(struct hstate *h,
				      struct vm_area_struct *vma,
				      unsigned long address);
int hugetlb_add_to_page_cache(struct folio *folio,
			      struct address_space *mapping, unsigned long idx);
void restore_reserve_on_error(struct hstate *h, struct vm_area_struct *vma,
			      unsigned long address, struct folio *folio);

int __attribute__((__section__(".init.text")))
__alloc_bootmem_huge_page(struct hstate *h, int nid);
int __attribute__((__section__(".init.text")))
alloc_bootmem_huge_page(struct hstate *h, int nid);
bool __attribute__((__section__(".init.text")))
hugetlb_node_alloc_supported(void);

void __attribute__((__section__(".init.text")))
hugetlb_add_hstate(unsigned order);
bool __attribute__((__section__(".init.text")))
arch_hugetlb_valid_size(unsigned long size);
struct hstate *size_to_hstate(unsigned long size);

extern struct hstate hstates[2];
extern unsigned int default_hstate_idx;

