__attribute__((no_instrument_function)) unsigned int
huge_page_order(struct hstate *h)
{
	return h->order;
}

static inline __attribute__((__gnu_inline__)) __attribute__((__unused__))
__attribute__((no_instrument_function)) unsigned
huge_page_shift(struct hstate *h)
{
	return h->order + 12;
}

static inline __attribute__((__gnu_inline__)) __attribute__((__unused__))
__attribute__((no_instrument_function)) bool
hstate_is_gigantic(struct hstate *h)
{
	return huge_page_order(h) > 10;
}

static inline __attribute__((__gnu_inline__)) __attribute__((__unused__))
__attribute__((no_instrument_function)) unsigned int
pages_per_huge_page(const struct hstate *h)
{
	return 1 << h->order;
}

static inline __attribute__((__gnu_inline__)) __attribute__((__unused__))
__attribute__((no_instrument_function)) unsigned int
blocks_per_huge_page(struct hstate *h)
{
	return huge_page_size(h) / 512;
}

