static inline __attribute__((__gnu_inline__)) __attribute__((__unused__))
__attribute__((no_instrument_function)) void
outsb(u16 port, const void *addr, unsigned long count)
{
	if (cc_platform_has(CC_ATTR_GUEST_UNROLL_STRING_IO)) {
		u8 *value = (u8 *)addr;
		while (count) {
			__outb(*value, port);
			value++;
			count--;
		}
	} else {
		asm volatile("rep; outs"
			     "b"
			     : "+S"(addr), "+c"(count)
			     : "d"(port)
			     : "memory");
	}
}
static inline __attribute__((__gnu_inline__)) __attribute__((__unused__))
__attribute__((no_instrument_function)) void
insb(u16 port, void *addr, unsigned long count)
{
	if (cc_platform_has(CC_ATTR_GUEST_UNROLL_STRING_IO)) {
		u8 *value = (u8 *)addr;
		while (count) {
			*value = __inb(port);
			value++;
			count--;
		}
	} else {
		asm volatile("rep; ins"
			     "b"
			     : "+D"(addr), "+c"(count)
			     : "d"(port)
			     : "memory");
	}
}
