static int check_unshare_flags(unsigned long unshare_flags)
{
	if (unshare_flags &
	    ~(0x00010000 | 0x00000200 | 0x00020000 | 0x00000800 | 0x00000100 |
	      0x00000400 | 0x00040000 | 0x04000000 | 0x08000000 | 0x40000000 |
	      0x10000000 | 0x20000000 | 0x02000000 | 0x00000080))
		return -22;

	if (unshare_flags & (0x00010000 | 0x00000800 | 0x00000100)) {
		if (!thread_group_empty(get_current()))
			return -22;
	}
	if (unshare_flags & (0x00000800 | 0x00000100)) {
		if (refcount_read(&get_current()->sighand->count) > 1)
			return -22;
	}
	if (unshare_flags & 0x00000100) {
		if (!current_is_single_threaded())
			return -22;
	}

	return 0;
}

static int unshare_fs(unsigned long unshare_flags, struct fs_struct **new_fsp)
{
	struct fs_struct *fs = get_current()->fs;

	if (!(unshare_flags & 0x00000200) || !fs)
		return 0;

	if (fs->users == 1)
		return 0;

	*new_fsp = copy_fs_struct(fs);
	if (!*new_fsp)
		return -12;

	return 0;
}

int unshare_fd(unsigned long unshare_flags, unsigned int max_fds,
	       struct files_struct **new_fdp)
{
	struct files_struct *fd = get_current()->files;
	int error = 0;

	if ((unshare_flags & 0x00000400) &&
	    (fd && atomic_read(&fd->count) > 1)) {
		*new_fdp = dup_fd(fd, max_fds, &error);
		if (!*new_fdp)
			return error;
	}

	return 0;
}
